import { context } from '@opentelemetry/api';
import { createDiagnosticContext, createTracingChannel } from '@platformatic/kafka';
export const consumerProcessesChannel = createTracingChannel('consumer:processes');
export function processWithTracing(payload, processor, callback) {
    const ctx = createDiagnosticContext({ message: payload });
    consumerProcessesChannel.start.publish(ctx);
    const activeContext = ctx.activeContext ?? context.active();
    if (callback) {
        const cbProcessor = processor;
        try {
            context.with(activeContext, () => {
                cbProcessor(payload, error => {
                    if (error) {
                        ctx.error = error;
                    }
                    consumerProcessesChannel.asyncStart.publish(ctx);
                    callback(error);
                });
            });
        }
        catch (error) {
            ctx.error = error;
            consumerProcessesChannel.asyncStart.publish(ctx);
            callback(error);
        }
        return;
    }
    try {
        const result = context.with(activeContext, () => {
            return processor(payload);
        });
        if (typeof result?.then !== 'function') {
            consumerProcessesChannel.asyncStart.publish(ctx);
            return;
        }
        return result.then(() => {
            consumerProcessesChannel.asyncStart.publish(ctx);
        }, error => {
            ctx.error = error;
            consumerProcessesChannel.asyncStart.publish(ctx);
            throw error;
        });
    }
    catch (error) {
        ctx.error = error;
        consumerProcessesChannel.asyncStart.publish(ctx);
        throw error;
    }
}
